import server from "./server";

const getBillList = async ({pageNumber,pageSize}) => {
    try {
        const res = await server.get(`/list/bill?pageNumber=${pageNumber}&pageSize=${pageSize}`)
        return res.data
    } catch (e) {
        console.log('获取数据错误',e.message);
        return false
    }
}
export default getBillList