
import { Switch, Route,Redirect } from 'react-router-dom';
import Navigitor from './components/Navigitor';
import Home from "./page/Home";
import Bill from "./page/Bill";
import Detail from './page/Detail';
import ForecastApportion from './page/ForecastApportion';
import UpLoad from './page/Upload';
import PictureWall from './page/PictureWall';
import Consumer from './page/Consumer';
import Subsidy from './page/Subsidy';

function App() {

  return (
    <div>
      <Navigitor />
      <Switch>
        <Route path="/index" component={Home}></Route>
        <Route path="/bill" component={Bill}></Route>
        <Route path="/consumer" component={Consumer}></Route>
        <Route path="/subsidy" component={Subsidy}></Route>
        <Route path="/detail/:id" component={Detail}></Route>
        <Route path="/forecastApportion" component={ForecastApportion}></Route>
        <Route path="/upload" component={UpLoad}></Route>
        <Route path="/pictureWall" component={PictureWall}></Route>
        <Redirect to='/index' />
      </Switch>
    </div>
  );
}

export default App;
