import React, { Component } from "react";
import { Container, Pagination } from "react-bootstrap";
import ListGroup from "react-bootstrap/ListGroup";
import BillList from "../../api/BillList";

export default class Bill extends Component {
  state = {
    list: { records: [], currentPage: 1 },
    currentPage: 1,
    itemsPerPage: 15,
    total: 0,
    currentPageItem: [],
    size: 0,
  };
  showDetail = (id = "0000") => {
    this.props.history.push("/detail/" + id);
  };

  //处理分页请求逻辑
  handlePageChange = async (pageId) => {
    const { list, itemsPerPage } = this.state;
    const item = list.find((item) => item.currentPage === pageId);
    console.log("data", item);
    if (item) {
      this.setState({
        currentPageItem: item.records,
        currentPage: pageId,
      });
    } else {
      const res = await BillList({
        pageNumber: pageId,
        pageSize: itemsPerPage,
      });
      this.setState({
        list: [...list, { records: res.data.records, currentPage: pageId }],
        currentPageItem: res.data.records,
        currentPage: pageId,
      });
    }
  };
  //处理分页点击切换逻辑
  get PageItems() {
    const { currentPage, total: totalPages } = this.state;
    const items = [];

    if (totalPages <= 1) {
      return items;
    }

    // 上一页
    items.push({
      key: "prev",
      type: "prev",
      disabled: currentPage === 1,
      label: "Previous",
    });

    if (totalPages <= 3) {
      // 页数少时全部显示
      for (let i = 1; i <= totalPages; i++) {
        items.push({
          key: i,
          type: "page",
          page: i,
          active: i === currentPage,
        });
      }
    } else {
      // 第一页
      items.push({ key: 1, type: "page", page: 1, active: currentPage === 1 });

      // 当前页附近范围
      let start = Math.max(2, currentPage - 1);
      let end = Math.min(totalPages - 1, currentPage + 1);

      if (start > 2) {
        items.push({ key: "leftEllipsis", type: "ellipsis" });
      }

      for (let i = start; i <= end; i++) {
        items.push({
          key: i,
          type: "page",
          page: i,
          active: i === currentPage,
        });
      }

      if (end < totalPages - 1) {
        items.push({ key: "rightEllipsis", type: "ellipsis" });
      }

      // 最后一页
      items.push({
        key: totalPages,
        type: "page",
        page: totalPages,
        active: currentPage === totalPages,
      });
    }

    // 下一页
    items.push({
      key: "next",
      type: "next",
      disabled: currentPage === totalPages,
      label: "Next",
    });

    return items;
  }
  get small() {
    return this.state.size < 576;
  }

  get lg() {
    return this.state.size >= 768;
  }
  async componentDidMount() {
    const { currentPage, itemsPerPage } = this.state;
    const res = await BillList({
      pageNumber: currentPage,
      pageSize: itemsPerPage,
    });
    this.setState({
      list: [{ records: res.data.records, currentPage }],
      currentPageItem: res.data.records,
      total: Math.ceil(res.data.total / itemsPerPage),
    });
    window.addEventListener("resize", () => {
      this.setState({ size: window.innerWidth });
    });
    this.setState({ size: window.innerWidth });
  }
  render() {
    const { currentPageItem: list } = this.state;
    return (
      <>
        <Container className="mt-3 opacity-75">
          <ListGroup className="mb-3">
            {list.map((item) => {
              return (
                <ListGroup.Item
                  as={"a"}
                  onClick={() => {
                    this.showDetail(item.list[0].id);
                  }}
                  key={item.list[0].id}
                  action
                >
                  <div className="d-flex w-100 justify-content-between">
                    <h3 className="mb-1">
                      ¥{item.list[0].consumeSum}{" "}
                      <span className="fs-6">
                        ({item.list[0].consumeAmount}度)
                      </span>
                    </h3>
                    <small className="fs-6">{item.list[0].consumeTime}</small>
                  </div>
                  <p className="mb-1">
                    消费方式:{item.list[0].consumeTypeName}
                  </p>
                  <p className="mb-1">交易状态:{item.list[0].statusName}</p>
                  <small>
                    使用时间:{item.list[0].lastReportTime} -{" "}
                    {item.list[0].reportTime}
                  </small>
                </ListGroup.Item>
              );
            })}
          </ListGroup>
          <Pagination
            className="d-flex justify-content-center "
            size={this.small ? "sm" : this.lg ? "lg" : ""}
          >
            {this.PageItems.map((item) => {
              if (item.type === "prev") {
                return (
                  <Pagination.Prev
                    key={item.key}
                    disabled={item.disabled}
                    onClick={() =>
                      this.handlePageChange(this.state.currentPage - 1)
                    }
                  >
                    {item.label}
                  </Pagination.Prev>
                );
              }

              if (item.type === "ellipsis") {
                return <Pagination.Ellipsis key={item.key} disabled />;
              }

              if (item.type === "next") {
                return (
                  <Pagination.Next
                    key={item.key}
                    disabled={item.disabled}
                    onClick={() =>
                      this.handlePageChange(this.state.currentPage + 1)
                    }
                  >
                    {item.label}
                  </Pagination.Next>
                );
              }

              return (
                <Pagination.Item
                  key={item.key}
                  active={item.active}
                  onClick={() => this.handlePageChange(item.page)}
                >
                  {item.page}
                </Pagination.Item>
              );
            })}
          </Pagination>
        </Container>
      </>
    );
  }
}
