import React from "react";
import { useEffect } from "react";
import { Container, ListGroup } from "react-bootstrap";
import getBillList from "../../api/BillList";
import getBalance from "../../api/balance";
import { useState } from "react";

export default function ForecastApportion() {
  const [avg, setAvg] = useState(0);
  const [balance, setBalance] = useState(0);

  useEffect(() => {
    async function f() {
      const res = await getBillList({ pageNumber: 1, pageSize: 7 });
      const resBalance = await getBalance();
      setBalance(resBalance.data.moneyBalance);
      console.log(res);
      const amount = res.data.records.map((item) => {
        return item.list[0].consumeSum;
      });

      setAvg((amount.reduce((sum, current) => sum + current, 0) / amount.length).toFixed(2));
    }
    f();
  }, []);
  return (
    <Container className="opacity-75 mt-3">
      <ListGroup>
        <ListGroup.Item>当前账号剩余余额:{balance}</ListGroup.Item>
        <ListGroup.Item>最近七天的使用电费的平均值:{avg}</ListGroup.Item>
        <ListGroup.Item>明天的电费预测:{balance - avg}</ListGroup.Item>
      </ListGroup>
    </Container>
  );
}
