import React, { Component } from "react";
import { Container, ListGroup } from "react-bootstrap";
import getConsumerList from "../../api/consumer";
export default class Consumer extends Component {
  state = { list: [{}] };
  async componentDidMount() {
    const { data } = await getConsumerList();
    this.setState({ list: data.records });
  }
  render() {
    const { list } = this.state;
    return (
      <Container className="mt-3 opacity-75">
        <ListGroup className="mb-3">
          {list.map((item) => {
            return (
              <ListGroup.Item as={"a"} key={item.id} action>
                <div className="d-flex w-100 justify-content-between">
                  <h3 className="mb-1">
                    状态:{" "}
                    <span className="text-primary">
                      {item.rechargeStatusName}
                    </span>
                  </h3>
                  <small className="fs-5 ">
                    金额:{""}
                    <span style={{ color: "#ffe211" }}>{item.rechargeSum}</span>
                  </small>
                </div>
                <p className="mb-1">时间: {item.rechargeTime}</p>
                <p className="mb-1">充值人: {item.name}</p>
                <small>订单号: {item.outTradeNo}</small>
              </ListGroup.Item>
            );
          })}
        </ListGroup>
      </Container>
    );
  }
}
